#!/usr/bin/env python3
"""universe-manager actor tests — deterministic, stdlib only, no network.

Builds a throwaway fixture universe in tempfile.mkdtemp():
  * two real component upstream git repos (quasar, star-lang), two commits
    each on main;
  * a universe repo with both as real git submodules: quasar pinned at
    its FIRST commit (stale), star-lang pinned at its HEAD (fresh);
  * .prolog/ control plane copied from the real repository
    (STARINTEL_UNIVERSE_ROOT, default ../../.. from this file);
  * machine facts generated by the actor's own `facts` subcommand
    (upstream heads resolve via offline `git ls-remote` on local paths).

Then drives the real actor CLI with the real swipl and asserts the
policy semantics of the tracked control plane.

Run:  python3 tests/actors/test_universe_manager.py -v
"""

import contextlib
import json
import os
import pathlib
import re
import shutil
import subprocess
import sys
import tempfile
import unittest

TEST_FILE = pathlib.Path(__file__).resolve()
DEFAULT_ROOT = TEST_FILE.parent.parent.parent
REPO_ROOT = pathlib.Path(
    os.environ.get("STARINTEL_UNIVERSE_ROOT", str(DEFAULT_ROOT))
).resolve()
ACTOR_BIN = REPO_ROOT / "actors" / "universe-manager" / "bin" / "universe-manager"

# (component atom, submodule path) — must be registered in .prolog/components.pl
STALE_COMPONENT, STALE_PATH = "quasar", "components/quasar"
FRESH_COMPONENT, FRESH_PATH = "star_lang", "components/star-lang"

# Every universe-level required check plus the stale component's native
# check (see .prolog/merge_policy.pl: required_check/2, component_check/2).
GREEN_CHECKS = {
    "unit": "green",
    "integration": "green",
    "actor_matrix": "green",
    "quasar_e2e": "green",
    "replay": "green",
    "packaging": "green",
    "quasar_native": "green",
}


def git(args, cwd, check=True):
    proc = subprocess.run(
        ["git"] + args,
        cwd=str(cwd),
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
    )
    if check and proc.returncode != 0:
        raise AssertionError(
            f"git {args} failed ({proc.returncode}): {proc.stderr.strip()}"
        )
    return proc


def make_component_repo(path, name):
    """Upstream repo with two commits on main; returns (first, head)."""
    path.mkdir(parents=True)
    git(["init", "-q", "-b", "main"], cwd=path)
    git(["config", "user.email", "universe-manager@test.local"], cwd=path)
    git(["config", "user.name", "universe-manager test"], cwd=path)
    (path / "file.txt").write_text(f"{name} one\n")
    git(["add", "."], cwd=path)
    git(["commit", "-qm", "c1"], cwd=path)
    first = git(["rev-parse", "HEAD"], cwd=path).stdout.strip()
    (path / "file.txt").write_text(f"{name} two\n")
    git(["commit", "-qam", "c2"], cwd=path)
    head = git(["rev-parse", "HEAD"], cwd=path).stdout.strip()
    return first, head


class UniverseManagerTests(unittest.TestCase):
    @classmethod
    def run_actor(cls, *args, expect=None):
        proc = subprocess.run(
            [sys.executable, str(ACTOR_BIN), *[str(a) for a in args]],
            cwd=str(cls.root),
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            text=True,
            timeout=120,
        )
        if expect is not None:
            if proc.returncode != expect:
                raise AssertionError(
                    f"actor {args} exit {proc.returncode} != {expect}\n"
                    f"stdout: {proc.stdout}\nstderr: {proc.stderr}"
                )
        return proc

    @classmethod
    def run_actor_json(cls, *args, expect=0):
        proc = cls.run_actor(*args, expect=expect)
        return json.loads(proc.stdout)

    @classmethod
    def setUpClass(cls):
        cls.root = pathlib.Path(tempfile.mkdtemp(prefix="universe-manager-test-"))
        upstream = cls.root / "upstream"
        upstream.mkdir()
        cls.stale_first, cls.stale_head = make_component_repo(
            upstream / "quasar", "quasar"
        )
        _, cls.fresh_head = make_component_repo(upstream / "star-lang", "star-lang")

        uni = cls.root / "universe"
        uni.mkdir()
        git(["init", "-q", "-b", "main"], cwd=uni)
        git(["config", "user.email", "universe-manager@test.local"], cwd=uni)
        git(["config", "user.name", "universe-manager test"], cwd=uni)

        def add_submodule(source, path, pin):
            git(
                ["-c", "protocol.file.allow=always", "submodule", "add", str(source), path],
                cwd=uni,
            )
            if pin:
                git(["checkout", "-q", pin], cwd=uni / path)
            git(["add", path], cwd=uni)

        add_submodule(upstream / "quasar", STALE_PATH, cls.stale_first)
        add_submodule(upstream / "star-lang", FRESH_PATH, None)
        git(["commit", "-qm", "universe fixture"], cwd=uni)

        shutil.copytree(REPO_ROOT / ".prolog", uni / ".prolog")
        cls.root = uni
        cls.scratch = pathlib.Path(tempfile.mkdtemp(prefix="universe-manager-scratch-"))
        cls.run_actor("facts", expect=0)

        cls.proposal = cls.run_actor_json(
            "propose", "--components", STALE_COMPONENT, expect=0
        )
        cls.assertTrue(
            cls.proposal["branch"].startswith("universe-update/"),
            cls.proposal["branch"],
        )
        proposal_path = cls.scratch / "proposal.json"
        proposal_path.write_text(json.dumps(cls.proposal, indent=2))
        applied = cls.run_actor_json("apply", str(proposal_path), expect=0)
        cls.branch = applied["branch"]
        cls.applied_commit = applied["commit"]
        cls.proposal_path = proposal_path

    @classmethod
    def tearDownClass(cls):
        shutil.rmtree(cls.root.parent, ignore_errors=True)
        shutil.rmtree(cls.scratch, ignore_errors=True)

    @contextlib.contextmanager
    def pristine(self):
        """Temporarily restore the pre-apply universe state (main branch,
        stale submodule pin) so inspect/discover/propose see real drift."""
        git(["checkout", "-q", "main"], cwd=self.root)
        git(["checkout", "-q", self.stale_first], cwd=self.root / STALE_PATH)
        try:
            yield
        finally:
            git(["checkout", "-q", self.branch], cwd=self.root)
            git(["checkout", "-q", self.stale_head], cwd=self.root / STALE_PATH)

    # ------------------------------------------------------------------

    def test_inspect_finds_both_components(self):
        with self.pristine():
            data = self.run_actor_json("inspect")
        by_name = {entry["component"]: entry for entry in data["components"]}
        self.assertIn(STALE_COMPONENT, by_name)
        self.assertIn(FRESH_COMPONENT, by_name)
        self.assertEqual(by_name[STALE_COMPONENT]["pin"], self.stale_first)
        self.assertEqual(by_name[STALE_COMPONENT]["head"], self.stale_head)
        self.assertEqual(by_name[FRESH_COMPONENT]["pin"], self.fresh_head)
        self.assertEqual(by_name[FRESH_COMPONENT]["head"], self.fresh_head)

    def test_discover_reports_exactly_the_stale_component(self):
        with self.pristine():
            changes = self.run_actor_json("discover")
        self.assertEqual(len(changes), 1, changes)
        only = changes[0]
        self.assertEqual(only["component"], STALE_COMPONENT)
        self.assertEqual(only["path"], STALE_PATH)
        self.assertEqual(only["from"], self.stale_first)
        self.assertEqual(only["to"], self.stale_head)

    def test_propose_stale_component_admissible(self):
        with self.pristine():
            proposal = self.run_actor_json("propose", "--components", STALE_COMPONENT)
        self.assertEqual(proposal["policy"], "admissible")
        self.assertTrue(
            re.fullmatch(r"universe-update/\d{8}-[0-9a-f]{8}", proposal["branch"])
        )
        change = proposal["changes"][0]
        self.assertEqual(change["component"], STALE_COMPONENT)
        self.assertEqual(change["from"], self.stale_first)
        self.assertEqual(change["to"], self.stale_head)
        notes = (self.root / "facts" / "notes.pl").read_text()
        self.assertIn("revalidates(quasar_ui)", notes)

    def test_propose_with_forged_from_is_denied(self):
        pins_path = self.root / "facts" / "pins.pl"
        original = pins_path.read_text()
        forged = original.replace(
            f"pin(quasar, '{self.stale_first}'",
            "pin(quasar, 'deadbeefdeadbeefdeadbeefdeadbeefdeadbeef'",
        )
        self.assertNotEqual(forged, original, "fixture pin not substituted")
        try:
            pins_path.write_text(forged)
            with self.pristine():
                result = self.run_actor_json(
                    "propose", "--components", STALE_COMPONENT, expect=1
                )
        finally:
            pins_path.write_text(original)
        self.assertEqual(result["policy"], "denied")
        self.assertTrue(
            any("candidate_rejected" in denial for denial in result["denials"]),
            result["denials"],
        )

    def test_gate_all_green_merge_allowed(self):
        checks_path = self.scratch / "green.json"
        checks_path.write_text(json.dumps(GREEN_CHECKS))
        result = self.run_actor_json(
            "gate",
            self.branch,
            "--proposal",
            self.proposal_path,
            "--checks-file",
            checks_path,
            expect=0,
        )
        self.assertEqual(result["policy"], "merge_allowed")

    def test_gate_one_red_check_denied(self):
        red = dict(GREEN_CHECKS)
        red["unit"] = "red"
        checks_path = self.scratch / "red.json"
        checks_path.write_text(json.dumps(red))
        result = self.run_actor_json(
            "gate",
            self.branch,
            "--proposal",
            self.proposal_path,
            "--checks-file",
            checks_path,
            expect=1,
        )
        self.assertEqual(result["policy"], "denied")
        self.assertTrue(
            any("required_check_not_green" in d for d in result["denials"]),
            result["denials"],
        )

    def test_promote_skip_stage_denied(self):
        result = self.run_actor_json(
            "promote", "candidate", "staging", self.applied_commit, expect=1
        )
        self.assertEqual(result["policy"], "denied")

    def test_promote_candidate_to_integration_allowed(self):
        result = self.run_actor_json(
            "promote", "candidate", "integration", self.applied_commit, expect=0
        )
        self.assertEqual(result["policy"], "allowed")


if __name__ == "__main__":
    unittest.main(verbosity=2)
